<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChatDotRound, Check, Download, Plus, Upload } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'

const props=defineProps<{token:string;permissions:string[]}>()
const route=useRoute(),router=useRouter(),loading=ref(false),error=ref('')
const rows=ref<any[]>([]),active=ref<any>(null),products=ref<any[]>([]),scenes=ref<any[]>([]),templates=ref<any[]>([]),rules=ref<any[]>([]),bomVersions=ref<any[]>([]),dashboard=ref<any>(null)
const question=ref(''),answer=ref<any>(null),rawRequirement=ref(String(route.query.requirement||'')),parsed=ref<any>(null),step=ref(0),bom=ref<any[]>([]),validation=ref<any>(null),selectedTemplate=ref<number|null>(null),preview=ref<any>(null)
const mappingTemplate=ref<any>(null),templateAnalysis=ref<any>(null),selectedCell=ref(''),mappingField=ref('project_name'),exportTab=ref('data')
const templateMapping=reactive({sheetName:'',placeholderMappings:{} as Record<string,string>,bomTemplateRow:1,bomColumnMappings:{} as Record<string,string>})
const projectForm=reactive({name:'',customer:'',region:'',scene_id:null as number|null,notes:''})
const ruleForm=reactive({code:'',name:'',rule_type:'REQUIRE',condition:{sceneId:null as number|null},action:{productId:null as number|null,quantity:1},enabled:true})
const documentDialog=ref(false),pendingDocument=ref<File|null>(null),editingDocument=ref<any>(null)
const documentForm=reactive({category:'产品资料',version:'V1.0',description:'',applicable_models:'',applicable_versions:'',center_type:'',center_id:null as number|null,knowledge_enabled:false})
const statusLabels:Record<string,string>={DRAFT:'需求整理',CONFIGURING:'配单中',CONFIRMED:'已确认',EXPORTED:'已导出',ARCHIVED:'已归档'}
const ruleTypeLabels:Record<string,string>={REQUIRE:'必选规则',QUANTITY:'数量规则',CONDITION:'条件规则',COMPATIBILITY:'兼容规则',EXCLUDE:'互斥规则',RECOMMEND:'推荐规则'}
const validationLabels:Record<string,string>={PASS:'校验通过',WARNING:'存在警告',ERROR:'存在错误'}
const requirementLabels:Record<string,string>={scene:'业务场景',upstreamKm:'上游覆盖距离（公里）',downstreamKm:'下游覆盖距离（公里）',ptzCount:'球机数量',ais:'AIS融合',ocr:'船名OCR',yaw:'偏航预警',continuousOperation:'7×24小时连续运行'}
const documentStatusLabels:Record<string,string>={DRAFT:'草稿',PUBLISHED:'已发布',CURRENT:'当前有效',HISTORICAL:'历史版本',OBSOLETE:'已废止',NOT_SYNCED:'未同步',PROCESSING:'同步中',SYNCED:'已同步',FAILED:'同步失败',OUTDATED:'待重新同步'}
const metricItems=computed(()=>[{key:'products',label:'产品',path:'/products'},{key:'algorithms',label:'算法',path:'/algorithms'},{key:'capabilities',label:'模型能力',path:'/model-capabilities'},{key:'scenes',label:'场景',path:'/scenes'},{key:'solutions',label:'方案',path:'/solutions'}])
const mappingFields=[{value:'project_name',label:'项目名称'},{value:'customer_name',label:'客户名称'},{value:'sales_name',label:'所属销售'},{value:'project_region',label:'项目地区'},{value:'export_date',label:'导出日期'},{value:'total_price',label:'项目总价'}]
const bomFields=[{value:'lineNo',label:'序号'},{value:'productName',label:'产品名称'},{value:'model',label:'型号'},{value:'quantity',label:'数量'},{value:'unit',label:'单位'},{value:'unitPrice',label:'项目单价'},{value:'subtotal',label:'小计'},{value:'purpose',label:'用途'},{value:'note',label:'备注'}]
const activeTemplateSheet=computed(()=>templateAnalysis.value?.sheets?.find((item:any)=>item.name===templateMapping.sheetName)||null)
const can=(name:string)=>props.permissions.includes(name)
async function api(url:string,options:any={}){const response=await fetch(url,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),Authorization:'Bearer '+props.token,...(options.headers||{})}});const data=response.status===204?null:await response.json();if(!response.ok)throw Error(data?.detail||'请求失败');return data}
async function load(){loading.value=true;error.value='';try{const name=String(route.name);if(name==='home')dashboard.value=await api('/api/dashboard');if(name==='projects')rows.value=await api('/api/projects');if(name==='project-detail'){active.value=await api('/api/projects/'+route.params.id);bom.value=JSON.parse(JSON.stringify(active.value.currentBomVersion?.items||[]));[templates.value,products.value,bomVersions.value]=await Promise.all([api('/api/excel-templates'),api('/api/products'),api('/api/projects/'+route.params.id+'/bom-versions')])}if(name==='bom-rules'){rules.value=await api('/api/bom/rules');products.value=await api('/api/products');scenes.value=await api('/api/scenes')}if(name==='excel-templates')templates.value=await api('/api/excel-templates');if(name==='documents')rows.value=await api('/api/documents');if(name==='ai-config'){scenes.value=await api('/api/scenes')}}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function ask(){if(!question.value.trim())return;loading.value=true;try{answer.value=await api('/api/ai/chat',{method:'POST',body:JSON.stringify({message:question.value})})}finally{loading.value=false}}
async function parseRequirement(){parsed.value=await api('/api/ai/config/parse',{method:'POST',body:JSON.stringify({raw_requirement:rawRequirement.value})});step.value=1}
async function createAndConfirm(){if(!projectForm.name||!projectForm.customer||!projectForm.scene_id)return ElMessage.warning('请填写项目名称、客户和场景');const project=await api('/api/projects',{method:'POST',body:JSON.stringify({...projectForm,raw_requirement:rawRequirement.value,requirements:parsed.value.parsedRequirement})});await api('/api/ai/config/confirm',{method:'POST',body:JSON.stringify({project_id:project.id,raw_requirement:rawRequirement.value,ai_parsed_requirement:parsed.value.parsedRequirement,user_adjusted_requirement:parsed.value.parsedRequirement,confirmed_requirement:parsed.value.parsedRequirement})});const recommended=await api('/api/bom/recommend',{method:'POST',body:JSON.stringify({project_id:project.id})});await router.push('/projects/'+project.id);bom.value=recommended.items;step.value=2}
async function saveBom(summary='销售人工调整'){const result=await api('/api/projects/'+route.params.id+'/bom-versions',{method:'POST',body:JSON.stringify({items:bom.value,change_summary:summary,source:'MANUAL_EDIT'})});active.value.currentBomVersion=result;bomVersions.value=await api('/api/projects/'+route.params.id+'/bom-versions');ElMessage.success('已创建不可变BOM版本 V'+result.version);return result}
async function validateBom(){validation.value=await api('/api/bom/validate',{method:'POST',body:JSON.stringify({project_id:Number(route.params.id)})});ElMessage.success('规则校验完成')}
async function makePreview(){if(!selectedTemplate.value)return ElMessage.warning('请选择Excel模板');preview.value=await api('/api/projects/'+route.params.id+'/export-preview?template_id='+selectedTemplate.value,{method:'POST'});exportTab.value='effect'}
async function saveAndPreview(){await saveBom('导出前数据调整');await makePreview()}
async function exportExcel(){if(!selectedTemplate.value)return ElMessage.warning('请选择Excel模板');const result=await api('/api/projects/'+route.params.id+'/export-excel?template_id='+selectedTemplate.value,{method:'POST'});const response=await fetch(result.downloadUrl,{headers:{Authorization:'Bearer '+props.token}});if(!response.ok){let message='Excel下载失败';try{message=(await response.json()).detail||message}catch{}throw Error(message)}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=result.fileName;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);ElMessage.success('Excel已生成并保存导出历史')}
async function createRule(){await api('/api/bom/rules',{method:'POST',body:JSON.stringify(ruleForm)});rules.value=await api('/api/bom/rules');Object.assign(ruleForm,{code:'',name:'',rule_type:'REQUIRE',condition:{sceneId:null},action:{productId:null,quantity:1},enabled:true});ElMessage.success('规则版本 V1 已建立')}
async function uploadTemplate(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.[0])return;const form=new FormData();form.append('file',input.files[0]);form.append('name',input.files[0].name.replace(/\.xlsx$/i,''));await api('/api/excel-templates',{method:'POST',body:form});templates.value=await api('/api/excel-templates');ElMessage.success('模板已上传')}
async function openTemplateMapping(item:any){mappingTemplate.value=item;templateAnalysis.value=await api('/api/excel-templates/'+item.id+'/analyze',{method:'POST'});const saved=templateAnalysis.value.mapping||{};templateMapping.sheetName=saved.sheetName||templateAnalysis.value.sheetNames[0];templateMapping.placeholderMappings={...(saved.placeholderMappings||{})};templateMapping.bomTemplateRow=saved.bomTemplateRow||1;templateMapping.bomColumnMappings={...(saved.bomColumnMappings||{})};selectedCell.value=''}
function sheetRows(sheet:any):any[][]{if(!sheet)return[];const cellMap=new Map<string,any>((sheet.cells||[]).map((cell:any)=>[cell.coordinate,cell]));const rowCount=Math.min(Math.max(sheet.maxRow||1,12),40),columnCount=Math.min(Math.max(sheet.maxColumn||1,10),26);return Array.from({length:rowCount},(_,row)=>Array.from({length:columnCount},(_,column)=>{const coordinate=columnName(column+1)+(row+1);return cellMap.get(coordinate)||{coordinate,row:row+1,column:column+1,value:''}}))}
function columnName(value:number){let result='';for(let current=value;current;current=Math.floor((current-1)/26))result=String.fromCharCode(65+(current-1)%26)+result;return result}
function chooseCell(cell:any){selectedCell.value=templateMapping.sheetName+'!'+cell.coordinate}
function mapSelectedCell(){if(!selectedCell.value)return ElMessage.warning('请先点击工作表中的单元格');templateMapping.placeholderMappings={...templateMapping.placeholderMappings,[mappingField.value]:selectedCell.value}}
async function saveTemplateMapping(){if(!mappingTemplate.value)return;await api('/api/excel-templates/'+mappingTemplate.value.id+'/mapping',{method:'POST',body:JSON.stringify({sheet_name:templateMapping.sheetName,placeholder_mappings:templateMapping.placeholderMappings,bom_template_row:templateMapping.bomTemplateRow,bom_column_mappings:templateMapping.bomColumnMappings})});ElMessage.success('模板映射已保存')}
function selectDocument(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.[0])return;editingDocument.value=null;pendingDocument.value=input.files[0];documentDialog.value=true;input.value=''}
function editDocument(row:any){editingDocument.value=row;pendingDocument.value=null;Object.assign(documentForm,{category:row.category||'产品资料',version:row.version||'V1.0',description:row.description||'',applicable_models:row.applicableModels||'',applicable_versions:row.applicableVersions||'',center_type:row.centerType||'',center_id:row.centerId||null,knowledge_enabled:Boolean(row.knowledgeEnabled)});documentDialog.value=true}
async function uploadDocument(){if(!pendingDocument.value)return;const form=new FormData();form.append('file',pendingDocument.value);Object.entries(documentForm).forEach(([key,value])=>{if(value!==null&&value!=='')form.append(key,String(value))});await api('/api/documents',{method:'POST',body:form});rows.value=await api('/api/documents');documentDialog.value=false;pendingDocument.value=null;Object.assign(documentForm,{category:'产品资料',version:'V1.0',description:'',applicable_models:'',applicable_versions:'',center_type:'',center_id:null,knowledge_enabled:false});ElMessage.success('资料已保存为草稿')}
async function saveDocumentMetadata(){if(!editingDocument.value)return uploadDocument();await api('/api/documents/'+editingDocument.value.id,{method:'PATCH',body:JSON.stringify({category:documentForm.category,version:documentForm.version,description:documentForm.description,applicable_models:documentForm.applicable_models,applicable_versions:documentForm.applicable_versions,center_type:documentForm.center_type||null,center_id:documentForm.center_id,knowledge_enabled:documentForm.knowledge_enabled})});rows.value=await api('/api/documents');documentDialog.value=false;editingDocument.value=null;ElMessage.success('资料信息已保存')}
async function publishDocument(row:any){await api('/api/documents/'+row.id+'/publish',{method:'POST'});if(row.knowledgeEnabled)await api('/api/documents/'+row.id+'/knowledge-sync',{method:'POST'});rows.value=await api('/api/documents');ElMessage.success(row.knowledgeEnabled?'资料已发布并同步知识库':'资料已发布')}
async function openDocument(row:any,download=false){const response=await fetch('/api/documents/'+row.id+(download?'/download':'/preview'),{headers:{Authorization:'Bearer '+props.token}});if(!response.ok){let message='文件访问失败';try{message=(await response.json()).detail||message}catch{}throw Error(message)}const blob=await response.blob(),url=URL.createObjectURL(blob);if(download){const link=document.createElement('a');link.href=url;link.download=row.originalFileName||row.name;link.click()}else window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}
function openSource(source:any){if(source.type==='documents')return openDocument(source);if(source.url)return router.push(source.url)}
function addBomRow(){bom.value.push({productId:products.value[0]?.id,productName:products.value[0]?.name,model:products.value[0]?.modelCode,quantity:1,unit:'台',unitPrice:0,purpose:'',note:'',manualEdited:true})}
function syncBomProduct(row:any){const product=products.value.find((item:any)=>item.id===row.productId);if(product){row.productName=product.name;row.model=product.modelCode;if(product.referencePrice!=null)row.unitPrice=product.referencePrice}row.manualEdited=true}
watch(()=>route.fullPath,load);onMounted(load)
</script>

<template>
 <div v-loading="loading" class="phase2"><el-alert v-if="error" :title="error" type="error" show-icon/>
  <template v-if="route.name==='home'">
   <section class="ai-panel"><div class="ai-title"><el-icon><ChatDotRound/></el-icon><div><h1>海智AI助手</h1><p>基于六大知识中心和当前有效资料回答产品问题</p></div></div><div class="ai-input"><el-input v-model="question" size="large" placeholder="请输入产品、软件、算法、模型、场景、方案或资料相关问题……" @keyup.enter="ask"/><el-button type="primary" size="large" @click="ask">发送</el-button><el-button v-if="can('BOM_EDIT')" size="large" @click="router.push('/ai-config')">智能配单</el-button></div><div class="quick"><button v-for="item in ['海智AI终端支持哪些算法？','有哪些雷达产品？','桥梁防撞有哪些标准方案？','帮我找AI终端使用说明书。']" :key="item" @click="question=item;ask()">{{item}}</button></div><article v-if="answer" class="ai-answer"><b>海智AI</b><p>{{answer.answer}}</p><div class="source-links"><button v-for="source in answer.sources" :key="source.type+source.id" type="button" @click="openSource(source)">{{source.name}}</button></div><el-button v-if="answer.configurationIntent&&can('BOM_EDIT')" type="primary" @click="router.push({path:'/ai-config',query:{requirement:answer.configurationInput}})">进入智能配单</el-button></article></section>
   <section v-if="dashboard" class="dashboard"><div class="metric-grid"><button v-for="item in metricItems" :key="item.key" class="metric" @click="router.push(item.path)"><strong>{{dashboard.metrics[item.key]||0}}</strong><span>{{item.label}}数量</span></button></div><div class="dashboard-grid"><article class="dashboard-block wide"><div class="block-head"><h2>核心产品</h2><el-button link @click="router.push('/products')">查看全部</el-button></div><div class="product-strip"><button v-for="item in dashboard.coreProducts" :key="item.id" @click="router.push('/products/'+item.id)"><img :src="item.image||'/assets/product-terminal.png'" :alt="item.name"/><span><b>{{item.name}}</b><small>{{item.modelCode}}</small></span></button></div></article><article class="dashboard-block"><div class="block-head"><h2>常用场景</h2></div><button v-for="item in dashboard.commonScenes" :key="item.id" class="list-row" @click="router.push('/scenes/'+item.id)"><span><b>{{item.name}}</b><small>{{item.category}}</small></span><em>查看</em></button></article><article v-if="can('BOM_VIEW')" class="dashboard-block"><div class="block-head"><h2>最近项目配单</h2><el-button link @click="router.push('/projects')">查看全部</el-button></div><el-empty v-if="!dashboard.recentProjects.length" description="暂无项目配单" :image-size="54"/><button v-for="item in dashboard.recentProjects" :key="item.id" class="list-row" @click="router.push('/projects/'+item.id)"><span><b>{{item.name}}</b><small>{{item.customer}} · {{statusLabels[item.status]}}</small></span><em>V{{item.bomVersion||0}}</em></button></article><article class="dashboard-block"><div class="block-head"><h2>最近更新</h2></div><button v-for="item in dashboard.recentUpdates" :key="item.type+item.id" class="list-row" @click="router.push(item.url)"><span><b>{{item.name}}</b><small>{{item.typeLabel}}</small></span><em>查看</em></button></article><article class="dashboard-block"><div class="block-head"><h2>热门模型能力</h2><el-button link @click="router.push('/model-capabilities')">查看全部</el-button></div><div class="capability-tags"><button v-for="item in dashboard.popularCapabilities" :key="item.id" @click="router.push('/model-capabilities/'+item.id)"><b>{{item.name}}</b><span>{{item.functionType}} · {{item.version}}</span></button></div></article></div></section>
  </template>
  <template v-else-if="route.name==='ai-config'"><div class="page-head"><div><h1>智能配单</h1><p>确认需求后，由规则引擎基于真实产品和标准方案生成BOM。</p></div></div><el-steps :active="step" finish-status="success"><el-step title="需求解析"/><el-step title="确认需求"/><el-step title="推荐BOM"/></el-steps><section class="work-card"><h2>项目建设需求</h2><el-input v-model="rawRequirement" type="textarea" :rows="7" placeholder="描述场景、范围、设备数量和需要的能力"/><el-button type="primary" @click="parseRequirement">AI解析需求</el-button></section><section v-if="parsed" class="work-card"><h2>结构化需求确认</h2><el-descriptions :column="3" border><el-descriptions-item v-for="(value,key) in parsed.parsedRequirement" :key="key" :label="requirementLabels[String(key)]||'补充需求'">{{value===true?'是':value===false?'否':value}}</el-descriptions-item></el-descriptions><div class="form-grid"><el-input v-model="projectForm.name" placeholder="项目名称"/><el-input v-model="projectForm.customer" placeholder="客户名称"/><el-input v-model="projectForm.region" placeholder="项目地区"/><el-select v-model="projectForm.scene_id" placeholder="业务场景"><el-option v-for="scene in scenes" :key="scene.id" :label="scene.name" :value="scene.id"/></el-select></div><el-button type="primary" :icon="Check" @click="createAndConfirm">确认需求并生成BOM</el-button></section></template>
  <template v-else-if="route.name==='projects'"><div class="page-head"><div><h1>项目配单</h1><p>管理需求、BOM版本、规则校验和Excel导出。</p></div><el-button type="primary" @click="router.push('/ai-config')">新建智能配单</el-button></div><el-empty v-if="!rows.length" description="暂无项目配单"/><el-table v-else :data="rows" @row-click="(row:any)=>router.push('/projects/'+row.id)"><el-table-column prop="name" label="项目名称" min-width="180"/><el-table-column prop="customer" label="客户"/><el-table-column prop="scene" label="场景"/><el-table-column label="状态"><template #default="scope"><el-tag>{{statusLabels[scope.row.status]}}</el-tag></template></el-table-column><el-table-column prop="bomVersion" label="当前BOM版本"/></el-table></template>
  <template v-else-if="route.name==='project-detail'&&active">
   <div class="page-head"><div><el-button link @click="router.push('/projects')">返回项目列表</el-button><h1>{{active.name}}</h1><p>{{active.customer}} · {{active.region}} · {{active.scene}}</p></div><el-tag size="large">{{statusLabels[active.status]}}</el-tag></div>
   <el-tabs>
    <el-tab-pane label="BOM编辑"><div class="bom-layout"><aside class="candidate"><h3>候选产品库</h3><p>从产品中心添加，型号会自动校验。</p><el-button :icon="Plus" @click="addBomRow">添加产品</el-button></aside><section class="bom-table"><div class="section-actions"><h3>当前BOM · V{{active.currentBomVersion?.version||0}}</h3><el-button @click="saveBom()">保存新版本</el-button></div><el-table :data="bom" border><el-table-column label="产品" min-width="190"><template #default="s"><el-select v-model="s.row.productId" filterable @change="syncBomProduct(s.row)"><el-option v-for="item in products" :key="item.id" :label="item.name" :value="item.id"/></el-select></template></el-table-column><el-table-column label="型号" min-width="150"><template #default="s"><el-input v-model="s.row.model"/></template></el-table-column><el-table-column label="数量" width="115"><template #default="s"><el-input-number v-model="s.row.quantity" :min="1"/></template></el-table-column><el-table-column label="单位" width="90"><template #default="s"><el-input v-model="s.row.unit"/></template></el-table-column><el-table-column v-if="can('PRICE_VIEW')" label="项目单价" width="150"><template #default="s"><el-input-number v-model="s.row.unitPrice" :min="0"/></template></el-table-column><el-table-column label="用途/备注" min-width="190"><template #default="s"><el-input v-model="s.row.purpose"/><el-input v-model="s.row.note"/></template></el-table-column><el-table-column width="70"><template #default="s"><el-button link type="danger" @click="bom.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table></section><aside class="validation"><h3>规则校验</h3><el-button type="primary" @click="validateBom">重新校验</el-button><el-result v-if="validation" :icon="validation.status==='PASS'?'success':validation.status==='WARNING'?'warning':'error'" :title="validationLabels[validation.status]" :sub-title="`通过 ${validation.passCount} · 警告 ${validation.warningCount} · 错误 ${validation.errorCount}`"/></aside></div></el-tab-pane>
    <el-tab-pane label="版本历史"><el-timeline><el-timeline-item v-for="item in bomVersions" :key="item.id" :timestamp="item.createdAt">V{{item.version}} · {{item.changeSummary}} · {{item.manualEdited?'人工调整':'规则推荐'}}</el-timeline-item></el-timeline></el-tab-pane>
    <el-tab-pane label="Excel导出"><div class="export-tools"><el-select v-model="selectedTemplate" placeholder="选择Excel模板"><el-option v-for="item in templates" :key="item.id" :label="item.name+' · V'+item.currentVersion" :value="item.id"/></el-select><el-button @click="makePreview">刷新效果预览</el-button><el-button type="primary" :icon="Download" @click="exportExcel">确认生成Excel</el-button></div><el-tabs v-model="exportTab" class="export-tabs"><el-tab-pane label="数据调整" name="data"><el-table :data="bom" border><el-table-column label="产品" min-width="180"><template #default="s"><el-select v-model="s.row.productId" filterable @change="syncBomProduct(s.row)"><el-option v-for="item in products" :key="item.id" :label="item.name" :value="item.id"/></el-select></template></el-table-column><el-table-column label="型号" min-width="140"><template #default="s"><el-input v-model="s.row.model"/></template></el-table-column><el-table-column label="数量" width="110"><template #default="s"><el-input-number v-model="s.row.quantity" :min="1"/></template></el-table-column><el-table-column label="单位" width="90"><template #default="s"><el-input v-model="s.row.unit"/></template></el-table-column><el-table-column label="项目单价" width="150"><template #default="s"><el-input-number v-model="s.row.unitPrice" :min="0"/></template></el-table-column><el-table-column label="用途" min-width="150"><template #default="s"><el-input v-model="s.row.purpose"/></template></el-table-column><el-table-column label="备注" min-width="150"><template #default="s"><el-input v-model="s.row.note"/></template></el-table-column><el-table-column width="70"><template #default="s"><el-button link type="danger" @click="bom.splice(s.$index,1)">删除</el-button></template></el-table-column></el-table><div class="export-save"><el-button :icon="Plus" @click="addBomRow">新增产品</el-button><el-button type="primary" @click="saveAndPreview">保存为新BOM版本并预览</el-button></div></el-tab-pane><el-tab-pane label="Excel效果预览" name="effect"><el-empty v-if="!preview" description="请先选择模板并生成效果预览"/><iframe v-else class="excel-effect" :srcdoc="preview.html" title="Excel效果预览" sandbox=""/></el-tab-pane></el-tabs></el-tab-pane>
