  <template v-else-if="route.name==='bom-rules'"><div class="page-head"><div><h1>BOM规则</h1><p>使用业务条件维护规则，每次修改自动保留版本。</p></div></div><section class="work-card"><div class="rule-grid"><el-input v-model="ruleForm.code" placeholder="规则编码"/><el-input v-model="ruleForm.name" placeholder="规则名称"/><el-select v-model="ruleForm.rule_type"><el-option v-for="item in Object.keys(ruleTypeLabels)" :key="item" :label="ruleTypeLabels[item]" :value="item"/></el-select><el-select v-model="ruleForm.condition.sceneId" placeholder="适用场景"><el-option v-for="item in scenes" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="ruleForm.action.productId" placeholder="规则关联产品"><el-option v-for="item in products" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-input-number v-model="ruleForm.action.quantity" :min="1"/><el-button type="primary" @click="createRule">创建规则</el-button></div></section><el-table :data="rules"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column label="类型"><template #default="s">{{ruleTypeLabels[s.row.ruleType]||'业务规则'}}</template></el-table-column><el-table-column prop="version" label="版本"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column></el-table></template>
  <template v-else-if="route.name==='excel-templates'">
   <div class="page-head"><div><h1>Excel模板</h1><p>保留公司原始Excel样式，支持占位符和可视化单元格映射。</p></div><label class="upload-button"><el-icon><Upload/></el-icon>上传 .xlsx<input type="file" accept=".xlsx" @change="uploadTemplate"/></label></div>
   <el-table :data="templates"><el-table-column prop="name" label="模板名称"/><el-table-column prop="description" label="说明"/><el-table-column prop="currentVersion" label="当前版本"/><el-table-column prop="updatedAt" label="更新时间"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="openTemplateMapping(s.row)">配置映射</el-button></template></el-table-column></el-table>
   <section v-if="mappingTemplate&&templateAnalysis" class="mapping-workspace"><div class="section-actions"><div><h2>{{mappingTemplate.name}} · 字段映射</h2><p>点击工作表单元格，再选择业务字段完成映射。</p></div><el-button type="primary" @click="saveTemplateMapping">保存映射</el-button></div><div class="mapping-toolbar"><el-select v-model="templateMapping.sheetName" placeholder="选择工作表"><el-option v-for="name in templateAnalysis.sheetNames" :key="name" :label="name" :value="name"/></el-select><el-select v-model="mappingField"><el-option v-for="field in mappingFields" :key="field.value" :label="field.label" :value="field.value"/></el-select><el-input :model-value="selectedCell" readonly placeholder="点击下方单元格"/><el-button @click="mapSelectedCell">映射到所选单元格</el-button></div><div class="mapped-fields"><el-tag v-for="field in mappingFields" :key="field.value" :type="templateMapping.placeholderMappings[field.value]?'success':'info'">{{field.label}}：{{templateMapping.placeholderMappings[field.value]||'未映射'}}</el-tag></div><div class="cell-sheet"><table v-if="activeTemplateSheet"><thead><tr><th></th><th v-for="cell in sheetRows(activeTemplateSheet)[0]" :key="cell.column">{{columnName(cell.column)}}</th></tr></thead><tbody><tr v-for="row in sheetRows(activeTemplateSheet)" :key="row[0].row"><th>{{row[0].row}}</th><td v-for="cell in row" :key="cell.coordinate" :class="{selected:selectedCell===templateMapping.sheetName+'!'+cell.coordinate,mapped:Object.values(templateMapping.placeholderMappings).includes(templateMapping.sheetName+'!'+cell.coordinate)}" :title="cell.coordinate" @click="chooseCell(cell)">{{cell.value}}</td></tr></tbody></table></div><div class="bom-mapping"><div><h3>BOM明细起始行</h3><el-input-number v-model="templateMapping.bomTemplateRow" :min="1"/></div><div class="bom-map-grid"><label v-for="field in bomFields" :key="field.value"><span>{{field.label}}</span><el-input v-model="templateMapping.bomColumnMappings[field.value]" placeholder="例如 A 或 A8"/></label></div></div></section>
  </template>
  <template v-else-if="route.name==='documents'"><div class="page-head"><div><h1>资料中心</h1><p>统一上传、预览、下载和同步当前有效知识资料。</p></div><label v-if="can('DOCUMENT_EDIT')" class="upload-button"><el-icon><Upload/></el-icon>上传资料<input type="file" accept=".pdf,.png,.jpg,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt" @change="selectDocument"/></label></div><el-empty v-if="!rows.length" description="暂无可查看资料"/><el-table v-else :data="rows"><el-table-column prop="name" label="资料名称" min-width="220"/><el-table-column prop="category" label="分类"/><el-table-column prop="version" label="版本"/><el-table-column label="发布状态"><template #default="s">{{documentStatusLabels[s.row.status]||'未知状态'}}</template></el-table-column><el-table-column label="有效性"><template #default="s">{{documentStatusLabels[s.row.documentStatus]||'未知状态'}}</template></el-table-column><el-table-column label="AI知识状态"><template #default="s">{{documentStatusLabels[s.row.knowledgeStatus]||'未启用'}}</template></el-table-column><el-table-column label="操作" width="330"><template #default="s"><el-button v-if="s.row.canPreview" link @click="openDocument(s.row)">在线预览</el-button><el-button v-if="s.row.canDownload" link @click="openDocument(s.row,true)">下载原文件</el-button><el-button v-if="can('DOCUMENT_EDIT')" link @click="editDocument(s.row)">编辑信息</el-button><el-button v-if="can('DOCUMENT_EDIT')&&s.row.status!=='PUBLISHED'" link type="primary" @click="publishDocument(s.row)">{{s.row.knowledgeEnabled?'发布并同步':'发布'}}</el-button></template></el-table-column></el-table></template>
 </div>
 <el-dialog v-model="documentDialog" :title="editingDocument?'编辑资料信息':'完善资料信息'" width="640px"><el-form label-position="top"><div class="document-form"><el-form-item :label="editingDocument?'资料文件':'待上传文件'" class="span-2"><el-input :model-value="editingDocument?.originalFileName||pendingDocument?.name" disabled/></el-form-item><el-form-item label="资料分类"><el-select v-model="documentForm.category"><el-option v-for="item in ['产品资料','软件资料','算法资料','模型资料','场景资料','方案资料','培训资料','投标资料']" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="资料版本"><el-input v-model="documentForm.version"/></el-form-item><el-form-item label="适用型号"><el-input v-model="documentForm.applicable_models" placeholder="多个型号用逗号分隔"/></el-form-item><el-form-item label="适用版本"><el-input v-model="documentForm.applicable_versions" placeholder="多个版本用逗号分隔"/></el-form-item><el-form-item label="关联知识中心"><el-select v-model="documentForm.center_type" clearable><el-option label="产品中心" value="products"/><el-option label="软件中心" value="software"/><el-option label="算法中心" value="algorithms"/><el-option label="模型能力中心" value="model-capabilities"/><el-option label="场景中心" value="scenes"/><el-option label="方案中心" value="solutions"/></el-select></el-form-item><el-form-item label="关联记录编号"><el-input-number v-model="documentForm.center_id" :min="1"/></el-form-item><el-form-item label="资料说明" class="span-2"><el-input v-model="documentForm.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="用于AI知识问答" class="span-2"><el-switch v-model="documentForm.knowledge_enabled" active-text="启用" inactive-text="暂不启用"/></el-form-item></div></el-form><template #footer><el-button @click="documentDialog=false">取消</el-button><el-button type="primary" @click="saveDocumentMetadata">{{editingDocument?'保存信息':'保存草稿'}}</el-button></template></el-dialog>
</template>

